// План specs/job-create-sms.md 1.1 (кейс .qa/tests/job-create-sms/JS-01). Admin, компания «test», десктоп 1440×900, EN.
// @writes: создаёт работу «QA-AUTO toasts #8ae966 …» с техником QA-F5 tech и в конце переводит её в Cancelled.
// send-sms перехвачен: тело проверяется до ответа, ответ — фейковый 422 recipient_invalid (реальный SMS не уходит).
// В конце selected-company-id возвращается на «test».
import { test, expect } from '../../fixtures';
import {
  QA_TECH, cancelJob, createJobWithQaTech, expectOnlyQaTech, fakeSmsRejected, restoreTest, startInTest, toastGeometry,
} from './job-sms-helpers';

test.describe('Job creation SMS: toasts (#8ae966)', () => {
  test('Create Job with technician: "Job Created Successfully!" and SMS toast are stacked without overlap, both readable #8ae966 @desktop @writes', async ({ asUser }) => {
    test.setTimeout(180_000);
    const page = await asUser('admin');
    await startInTest(page);
    const smsCalls = await fakeSmsRejected(page);
    let jobUrl = '';
    try {
      const created = await createJobWithQaTech(page, `QA-AUTO toasts #8ae966 ${Date.now().toString(36)}`);
      jobUrl = created.jobUrl;

      // Оба toast на экране (источник: «מה רצוי» — שתי ההודעות מוצגות... ושתיהן קריאות).
      const green = 'Job Created Successfully!';
      const smsTitle = new RegExp(`^The SMS to ${QA_TECH.name}\\b|^${QA_TECH.name} was notified`);
      await expect(page.getByText(green, { exact: true }).first()).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText(smsTitle).first()).toBeVisible({ timeout: 20_000 });
      expect(smsCalls.length, 'был запрос send-sms (перехвачен)').toBeGreaterThan(0);

      // Стопкой: контейнеры не пересекаются, зазор ≥ 4px (на ручной проверке ~8px), в одной колонке;
      // заголовок каждого toast ничем не накрыт (элемент в его центре — внутри своего toast).
      await expect.poll(async () => {
        const geo = await toastGeometry(page, green, smsTitle);
        return { overlap: geo.overlap, stackedGap: geo.gap >= 4, greenReadable: geo.greenOnTop, smsReadable: geo.smsOnTop };
      }, { message: 'toast «Job Created Successfully!» и toast SMS — стопкой и оба читаются', timeout: 5_000 })
        .toEqual({ overlap: false, stackedGap: true, greenReadable: true, smsReadable: true });

      const geo = await toastGeometry(page, green, smsTitle);
      const xOverlap = Math.min(geo.green.right, geo.sms.right) - Math.max(geo.green.left, geo.sms.left);
      expect(xOverlap, 'toast в одной колонке (один под другим)').toBeGreaterThan(0);
    } finally {
      await cancelJob(page, jobUrl);
      await restoreTest(page);
    }
    expectOnlyQaTech(smsCalls);
  });
});
